// Input Validation & Mode Detection
const body = $('1.1_TRG_Webhook').first().json.body;

if (!body) {
  return [{ json: {
    validation_passed: false,
    error_message: 'No request body received'
  }}];
}

// Detect what inputs are present
const hasNewExtraction = !!(body.document_summary && body.document_summary.trim().length > 0);
const hasCurrentMemory = !!(body.current_project_memory && body.current_project_memory.trim().length > 0);

// Determine processing mode
let mode, modeDescription;
if (!hasCurrentMemory) {
  mode = '2A_INITIAL';
  modeDescription = 'First extraction - building initial memory';
} else if (hasNewExtraction) {
  mode = '2B_DOCUMENT_MERGE';
  modeDescription = 'Merging new document with existing memory';
} else {
  mode = '2C_CORRECTIONS';
  modeDescription = 'Processing user corrections only';
}

// Validate mode-specific requirements
if (mode === '2A_INITIAL' && !hasNewExtraction) {
  return [{ json: {
    validation_passed: false,
    error_message: 'Mode 2A requires document_summary for initial build'
  }}];
}

if (mode === '2C_CORRECTIONS') {
  const hasAnswers = body.clarification_answers && body.clarification_answers.length > 0;
  const hasCorrections = body.freeform_corrections && body.freeform_corrections.trim().length > 0;
  if (!hasAnswers && !hasCorrections) {
    return [{ json: {
      validation_passed: false,
      error_message: 'Mode 2C requires either clarification_answers or freeform_corrections'
    }}];
  }
}

// Build input_data matching the spec schema
const input_data = {};

if (hasNewExtraction) {
  input_data.new_extraction = {
    filename: body.file_type || 'unknown',
    document_summary: body.document_summary,
    ai_observations: body.ai_observations || null
  };
} else {
  input_data.new_extraction = null;
}

input_data.current_project_memory_text = hasCurrentMemory ? body.current_project_memory : null;
input_data.clarification_answers = body.clarification_answers || null;
input_data.freeform_corrections = body.freeform_corrections || null;

return [{ json: {
  validation_passed: true,
  mode: mode,
  mode_description: modeDescription,
  input_data: input_data,
  project_id: body.project_id,
  client_id: body.client_id,
  meeting_note_id: body.meeting_note_id
}}];

// Step 2 (Doc path): Parse extraction + format merge prompt
const extractResult = $input.first().json;
const validated = $('1.2_VAL_Input').first().json;
const inputData = validated.input_data;

// Parse extraction result
let extraction = extractResult.llm_response;
if (typeof extraction === 'string') {
  try { extraction = JSON.parse(extraction); } catch (e) {
    return [{ json: { _error: 'Failed to parse Step 1 extraction: ' + e.message }}];
  }
}

const systemPrompt = "# MEMORY MERGE AGENT

You are an AI agent that maintains "Project Memory" for consulting projects at Jombay (HR tech, L&D sector). Your job is to merge new information into an existing project memory document.

## CORE PRINCIPLES

1. **Merge factual information AS STATED** — preserve exact stakeholder language
2. **Preserve context and nuances** — don't lose important details
3. **NEVER modify proper nouns** — company names, people names, locations must be preserved EXACTLY as they appear in the input, even if they seem misspelled or unfamiliar
4. **Organizational coherence** — All references to the client must use ONE consistent name. If the extraction contains aliases (e.g., "Aarti Industries" and "AI"), pick the full formal name and use it everywhere. Never split one organization into multiple entities.
5. **Speaker vs participant awareness** — People who SPOKE in meetings (FGD facilitators, HR leaders giving briefs) are not necessarily PARTICIPANTS in the program. Only list someone as a participant/target audience if the inputs explicitly describe them as such.
6. **Identify conflicts and flag them** — don't resolve conflicts yourself
7. **Check if new info answers previous questions** — resolve them silently
8. **Maintain clean, readable structure**

## MEMORY STRUCTURE GUIDELINES

Use these sections as needed. Adapt based on actual content:

1. **Project Overview** — Factual description, what is being delivered
2. **Client Context** — Background about client, industry, size (use ONLY information from the input — do NOT use AI knowledge to fill in or correct details)
3. **Business Problem** — Core challenge, current state issues, why project exists
4. **Target Audience Description** — Who is impacted/involved, characteristics, needs. IMPORTANT: Only include people explicitly identified as participants/target audience in the inputs. Do NOT include meeting speakers, interviewees, or HR stakeholders unless the inputs explicitly say they are also participants.
5. **Stakeholder Expectations** — What stakeholders want, attributed to specific people
6. **Success Criteria** — How success will be measured, metrics, KPIs
7. **Constraints & Realities** — Limitations, ground realities, resource constraints
8. **Key Decisions Taken** — Concrete decisions, who decided, when, rationale
9. **Open Questions** — Questions raised by client/stakeholders, unresolved points
10. **Behavioral Observations** — Patterns, dynamics, culture notes
11. **Potential Risks** — Risks identified or implied

Section rules:
- Only include sections with actual content
- Add new sections if needed (e.g., "Technical Requirements", "Budget Breakdown")
- Maintain chronological flow within sections
- Use markdown formatting: headers, lists, emphasis
- Attribute statements to speakers when known

## CONFLICT DETECTION

When new information contradicts existing memory:
1. DO NOT choose a version yourself
2. FLAG it in the memory with: "[CONFLICT — See changes_made.conflicts_detected]"
3. Record both versions in conflicts_detected

## NATURAL QUESTION RESOLUTION

When new information answers previous clarification questions or open questions:
1. Update memory silently with the answer
2. Record which questions were resolved in changes_made
3. Don't mention the question was answered — just update memory naturally

## OUTPUT FORMAT

Return ONLY valid JSON:

{
  "project_memory_text": "# Project Memory\n\n## Section...\n...",
  "changes_made": {
    "sections_updated": ["list of section names that were modified or created"],
    "conflicts_detected": [
      {
        "section": "section name",
        "existing_value": "what memory currently says",
        "new_value": "what new information says",
        "description": "brief description of the conflict"
      }
    ],
    "questions_resolved": [
      {
        "question_summary": "brief description of the question that was answered",
        "resolution": "how it was resolved"
      }
    ],
    "summary": "1-2 sentence summary of what changed"
  }
}

Requirements:
- project_memory_text is a complete markdown string (not a diff — full updated memory)
- changes_made.sections_updated lists ALL sections that were touched
- conflicts_detected can be empty array if no conflicts
- questions_resolved can be empty array if no questions were answered
- Use \n for line breaks in markdown text";

// Build merge input based on mode
let mergeInput;
if (validated.mode === '2A_INITIAL') {
  mergeInput = {
    mode: '2A_INITIAL',
    mode_description: 'Building initial project memory from first document',
    extracted_information: extraction,
    current_project_memory_text: null,
    client_name: extraction.client_name || null
  };
} else {
  // 2B — merge with existing
  mergeInput = {
    mode: '2B_DOCUMENT_MERGE',
    mode_description: 'Merging new document extraction into existing memory',
    extracted_information: extraction,
    current_project_memory_text: inputData.current_project_memory_text,
    client_name: extraction.client_name || null
  };
}

const fullPrompt = systemPrompt + '

# INPUT

' + JSON.stringify(mergeInput, null, 2);

return [{ json: {
  prompt: fullPrompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  max_tokens: 8000,
  node_name: 'PMU_STEP2_MERGE_DOC',
  workflow_session_id: validated.meeting_note_id || '',
  workflow_id: 'project-memory-updater',
  project_id: validated.project_id || '',
  client_id: validated.client_id || ''
}}];

// Step 3: Parse merge output + format questions prompt + carry forward memory & changes
const mergeResult = $input.first().json;
const validated = $('1.2_VAL_Input').first().json;

// Parse merge result
let mergeData = mergeResult.llm_response;
if (typeof mergeData === 'string') {
  try { mergeData = JSON.parse(mergeData); } catch (e) {
    return [{ json: { _error: 'Failed to parse Step 2 merge output: ' + e.message }}];
  }
}

if (!mergeData || !mergeData.project_memory_text) {
  return [{ json: { _error: 'Step 2 output missing project_memory_text' }}];
}

const systemPrompt = "# QUESTION GENERATION AGENT

You are an AI agent that analyzes project memory and generates clarification questions for consulting projects at Jombay (HR tech, L&D sector).

## YOUR TASK

Analyze the updated project memory and generate a MAXIMUM of 3 critical clarification questions. Focus only on the most important gaps, conflicts, or ambiguities.

## QUESTION PRIORITIES

- HIGH: Blocks progress, affects deliverables/timeline/budget, involves money/resources
- MEDIUM: Important but doesn't block immediate work, affects scope/approach/quality
- LOW: Nice-to-have clarity, doesn't impact immediate work

## QUESTION CATEGORIES

- CONFLICT: Contradictory information from different sources
- GAP: Missing critical information needed to proceed
- AMBIGUITY: Unclear or vague statement needing specificity
- VERIFICATION: Confirm assumption or interpretation

## RULES

- Generate MAX 3 questions (fewer is better if memory is clear)
- Focus on what would be MOST useful for the consultant
- Don't ask about information that's already clear in the memory
- Each question must be specific and actionable
- Provide AI recommendations with reasoning

## OUTPUT FORMAT

Return ONLY valid JSON:

{
  "clarification_questions": [
    {
      "id": "CQ-001",
      "priority": "HIGH | MEDIUM | LOW",
      "category": "CONFLICT | GAP | AMBIGUITY | VERIFICATION",
      "question": "Specific, actionable question",
      "what_we_currently_have": "Current state showing the issue",
      "what_answer_should_look_like": "Example of good answer",
      "ai_recommendation": {
        "suggestion": "Recommended answer/action",
        "reasoning": "Why this recommendation makes sense",
        "confidence": "HIGH | MEDIUM | LOW — with brief explanation"
      }
    }
  ]
}

Requirements:
- clarification_questions is an array (can be empty [] if memory is complete and clear)
- Maximum 3 questions
- All fields in each question object are required
- Auto-generate sequential IDs: CQ-001, CQ-002, CQ-003
- Be specific about what information is needed";

const questionInput = {
  project_memory_text: mergeData.project_memory_text,
  changes_made: mergeData.changes_made || null,
  mode: validated.mode,
  mode_description: validated.mode_description
};

const fullPrompt = systemPrompt + '

# INPUT

' + JSON.stringify(questionInput, null, 2);

return [{ json: {
  prompt: fullPrompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  max_tokens: 2000,
  node_name: 'PMU_STEP3_QUESTIONS',
  workflow_session_id: validated.meeting_note_id || '',
  workflow_id: 'project-memory-updater',
  project_id: validated.project_id || '',
  client_id: validated.client_id || '',
  // Carry forward Step 2 outputs for JS_Package
  _step2_memory: mergeData.project_memory_text,
  _step2_changes: mergeData.changes_made || null
}}];

// Package final output: combine Step 2 memory + Step 3 questions
const questionsResult = $input.first().json;
const validated = $('1.2_VAL_Input').first().json;
const fmtQuestionsData = $('3.2_FMT_Questions').first().json;

// Get carried-forward Step 2 data
const step2Memory = fmtQuestionsData._step2_memory;
const step2Changes = fmtQuestionsData._step2_changes;

if (!step2Memory) {
  return [{ json: {
    memory_status: 'error',
    error_message: 'Step 2 memory not available in package step',
    project_id: validated.project_id,
    client_id: validated.client_id,
    meeting_note_id: validated.meeting_note_id
  }}];
}

// Parse questions result
let questionsData = questionsResult.llm_response;
if (typeof questionsData === 'string') {
  try { questionsData = JSON.parse(questionsData); } catch (e) {
    // Non-fatal: proceed with empty questions
    questionsData = { clarification_questions: [] };
  }
}

const questions = Array.isArray(questionsData.clarification_questions)
  ? questionsData.clarification_questions
  : [];

// Determine status
let memory_status = 'updated';
if (questions.length > 0) {
  memory_status = 'clarification_needed';
}

return [{ json: {
  memory_status: memory_status,
  current_project_memory: step2Memory,
  clarification_questions: questions,
  metadata: {
    changes_made: step2Changes,
    mode: validated.mode,
    mode_description: validated.mode_description
  },
  project_id: validated.project_id,
  client_id: validated.client_id,
  meeting_note_id: validated.meeting_note_id
}}];

// Format error for API reporting
const input = $input.first().json;

// Handle errors from validation, LLM failure, parse failure, or _error carry-through
const errorMessage = input._error
  || input.error_message
  || (input.error ? input.error.message : null)
  || input.errorMessage
  || 'Unknown error occurred';

let webhookBody;
try {
  webhookBody = $('1.1_TRG_Webhook').first().json.body;
} catch (e) {
  webhookBody = {};
}

return [{ json: {
  memory_status: 'error',
  error_message: errorMessage,
  project_id: webhookBody.project_id || input.project_id || '',
  client_id: webhookBody.client_id || input.client_id || '',
  meeting_note_id: webhookBody.meeting_note_id || input.meeting_note_id || ''
}}];
